#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_SIZE 32

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    // Shared memory for tiles
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    float sum = 0.0f;

    // Loop over tiles
    for (int t = 0; t < (N + TILE_SIZE - 1) / TILE_SIZE; t++) {
        int tiled_index = t * TILE_SIZE;

        // Load tile from A and B into shared memory
        int load_row = row;
        int load_col = tiled_index + threadIdx.x;
        if (load_row < N && load_col < N) {
            As[threadIdx.y][threadIdx.x] = A[load_row * N + load_col];
        } else {
            As[threadIdx.y][threadIdx.x] = 0.0f;
        }

        load_row = tiled_index + threadIdx.y;
        load_col = col;
        if (load_row < N && load_col < N) {
            Bs[threadIdx.y][threadIdx.x] = B[load_row * N + load_col];
        } else {
            Bs[threadIdx.y][threadIdx.x] = 0.0f;
        }

        __syncthreads();

        // Compute partial dot product
        for (int k = 0; k < TILE_SIZE; k++) {
            sum += As[threadIdx.y][k] * Bs[k][threadIdx.x];
        }

        __syncthreads();
    }

    // Write result to global memory
    if (row < N && col < N) {
        C[row * N + col] = sum;
    }
}

